INSERT INTO estrategias_didacticas (titulo, objetivo, paso_a_paso, id_admin1, id_docente2, condicion, materia, grado) VALUES
('Suma de dos cifras paso a paso', 'Construir la suma con dos cifras partiendo de lo concreto antes de la operacion escrita.', 'Representa cada numero con bloques o fichas agrupadas de diez y unidades.|Junta los grupos de diez primero y cuenta el total.|Junta las unidades sueltas y cuenta el total.|Dibuja los grupos en el cuaderno en vez de los objetos.|Escribe la operacion con numeros y comparala con el dibujo.', 1, 1, 'Autismo (TEA)', 'Matematicas', '2°'),
('Clasificacion y conteo por color', 'Desarrollar conteo y clasificacion como base antes de operaciones matematicas.', 'Entrega una mezcla de objetos de distintos colores.|Pide separarlos en montones por color.|Cuenta en voz alta cuantos hay en cada monton.|Compara que monton tiene mas y cual menos usando las palabras mas/menos.|Registra el resultado en una tabla sencilla con dibujos.', 1, 1, 'Autismo (TEA)', 'Matematicas', '2°'),
('Video modelado para una rutina matematica', 'Ensenar una secuencia matematica nueva mostrando el paso a paso en video o imagenes.', 'Graba o busca un video corto que muestre la actividad matematica completa.|Muestra el video al alumno antes de pedirle que la realice.|Pausa el video en cada paso y pide que lo repita con material concreto.|Repite el video las veces que sea necesario sin apresurar.|Retira el apoyo del video gradualmente conforme domine la secuencia.', 1, 1, 'Autismo (TEA)', 'Matematicas', '2°'),
('Guion social para pedir ayuda', 'Ensenar de forma explicita a pedir ayuda cuando algo resulta dificil.', 'Explica la situacion concreta: cuando no entiendo un ejercicio, puedo pedir ayuda.|Practica la frase exacta que puede usar: Maestra, no entendi, me ayuda.|Practica el guion en un juego de roles antes de la clase real.|Coloca una tarjeta con la frase en su escritorio como recordatorio visual.|Refuerza cada vez que el alumno la usa correctamente en clase.', 1, 1, 'Autismo (TEA)', 'Comunicacion', '2°'),
('Agenda visual de transicion entre actividades', 'Reducir la ansiedad ante cambios de actividad usando anticipacion visual.', 'Prepara una franja con tarjetas que muestren el orden de las actividades del dia.|Antes de cada cambio, senala la tarjeta actual y la siguiente.|Avisa verbalmente con frases cortas: en dos minutos cambiamos a...|Retira la tarjeta de la actividad terminada junto con el alumno.|Cierra el dia repasando juntos las tarjetas completadas.', 1, 1, 'Autismo (TEA)', 'Regulacion sensorial', '2°'),
('Espera con temporizador visual', 'Apoyar la espera de turnos con una referencia visual del tiempo.', 'Usa un temporizador visual tipo reloj de arena o disco de colores.|Explica que mientras el color este visible, es turno de otro companero.|Coloca el temporizador donde el alumno pueda verlo todo el tiempo.|Avisa cuando quede poco tiempo senalando el temporizador.|Reconoce en voz alta cuando el alumno espero su turno completo.', 1, 1, 'Autismo (TEA)', 'Habilidades sociales', '2°');